'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var typedarray = require( '@stdlib/array/typed' );
var Int64Array = require( '@stdlib/array/int64' );
var Number = require( '@stdlib/number/ctor' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var addon = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( addon instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof addon, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided an argument which is not a Uint32Array', opts, function test( t ) {
	var values;
	var i;

	values = [
		'5',
		true,
		false,
		null,
		void 0,
		[],
		{},
		typedarray( 10, 'int32' ),
		typedarray( 10, 'float64' )
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided '+values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			addon( 1, value, 1 );
		};
	}
});

tape( 'the function throws an error if provided an array having insufficient elements', opts, function test( t ) {
	var x = new Int64Array( 2 );

	t.throws( badValue, RangeError, 'throws an error' );
	t.end();

	function badValue() {
		addon( 10, x, 1 );
	}
});

tape( 'the function does not throw an error if provided an Int64Array', opts, function test( t ) {
	var v;
	var i;
	var j;

	v = [
		new Int64Array( 1 ),
		new Int64Array( 2 ),
		new Int64Array( 3 )
	];
	for ( i = 0; i < v.length; i++ ) {
		addon( v[ i ].length, v[ i ], 1 );
		for ( j = 0; j < v[ i ].length; j++ ) {
			t.strictEqual( Number( v[ i ].get( j ) ), j+1, 'returns expected value for element '+j+' of an array of length '+v[ i ].length );
		}
	}
	t.end();
});

tape( 'the function supports a stride parameter resolved in 64-bit elements', opts, function test( t ) {
	var x = new Int64Array( 4 );

	addon( 2, x, 2 );

	t.strictEqual( Number( x.get( 0 ) ), 1, 'returns expected value' );
	t.strictEqual( Number( x.get( 1 ) ), 0, 'returns expected value' );
	t.strictEqual( Number( x.get( 2 ) ), 2, 'returns expected value' );
	t.strictEqual( Number( x.get( 3 ) ), 0, 'returns expected value' );
	t.end();
});
